import { spawn, spawnSync } from 'node:child_process';
import fs from 'node:fs';
import path from 'node:path';

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

function ensureDir(dir) { fs.mkdirSync(dir, { recursive: true }); }
function isWin() { return process.platform === 'win32'; }
function npmCmd() { return isWin() ? 'npm.cmd' : 'npm'; }

function pidsOnPort(port) {
  if (!port) return [];
  if (!isWin()) {
    const r = spawnSync('sh', ['-lc', `lsof -ti tcp:${Number(port)} 2>/dev/null || true`], { encoding: 'utf8' });
    return [...new Set((r.stdout || '').split(/\s+/).map(x => Number(x)).filter(Boolean))];
  }
  const r = spawnSync('netstat', ['-ano', '-p', 'TCP'], { encoding: 'utf8' });
  const pids = [];
  const portRe = new RegExp(`:${Number(port)}\\s+`, 'i');
  for (const line of (r.stdout || '').split(/\r?\n/)) {
    if (!/LISTENING/i.test(line)) continue;
    if (!portRe.test(line)) continue;
    const m = line.trim().match(/(\d+)$/);
    if (m) pids.push(Number(m[1]));
  }
  return [...new Set(pids)];
}

async function urlOk(url) {
  try {
    const res = await fetch(url, { signal: AbortSignal.timeout(3000) });
    return { ok: res.ok, status: res.status, text: await res.text().then(t => t.slice(0, 200)).catch(() => '') };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

async function isAlphaLabFrontend(baseUrl) {
  try {
    const res = await fetch(`${baseUrl}/src/Workspace.tsx`, { signal: AbortSignal.timeout(3000) });
    const text = await res.text();
    const ct = res.headers.get('content-type') || '';
    const looksLikeJs = ct.includes('javascript') || ct.includes('ecmascript') || text.includes('import');
    const notHtmlFallback = !text.trimStart().startsWith('<!DOCTYPE html>') && !text.trimStart().startsWith('<html');
    const hasAlphaLabSignals = /AlphaLab|Workstation|Dockview|widget catalog|ModeSidebar|RightRail/i.test(text);
    return { ok: Boolean(res.ok && looksLikeJs && notHtmlFallback && hasAlphaLabSignals), status: res.status, contentType: ct, sample: text.slice(0, 200) };
  } catch (e) {
    return { ok: false, error: e.message };
  }
}

async function waitFor(url, timeoutMs, checker = null) {
  const started = Date.now();
  let last = null;
  while (Date.now() - started < timeoutMs) {
    last = checker ? await checker(url) : await urlOk(url);
    if (last.ok) return last;
    await sleep(1000);
  }
  return last ?? { ok: false, error: 'not checked' };
}

function startDetached(command, args, cwd, logFile) {
  const out = fs.openSync(logFile, 'a');
  let actualCommand = command;
  let actualArgs = args;
  if (isWin() && /(?:^|\\\\|\/)npm(?:\.cmd)?$/i.test(command)) {
    actualCommand = 'cmd.exe';
    actualArgs = ['/d', '/s', '/c', 'npm', ...args];
  }
  const child = spawn(actualCommand, actualArgs, { cwd, detached: true, stdio: ['ignore', out, out], windowsHide: true, shell: false });
  child.unref();
  return child.pid;
}

function runChecked(command, args, cwd, timeoutMs) {
  return spawnSync(command, args, { cwd, encoding: 'utf8', timeout: timeoutMs, shell: false });
}

async function chooseFrontendPort(preferredPort) {
  const preferredUrl = `http://localhost:${preferredPort}`;
  const preferredHttp = await urlOk(preferredUrl);
  if (!preferredHttp.ok) return { port: preferredPort, reused: false, reason: 'preferred port is free' };
  const preferredAlpha = await isAlphaLabFrontend(preferredUrl);
  if (preferredAlpha.ok) return { port: preferredPort, reused: true, reason: 'preferred port already runs AlphaLab frontend', alphaCheck: preferredAlpha };
  for (let port = preferredPort + 1; port <= preferredPort + 30; port += 1) {
    const probe = await urlOk(`http://localhost:${port}`);
    if (!probe.ok) return { port, reused: false, reason: `preferred port ${preferredPort} is occupied by another service; selected free port ${port}`, occupiedCheck: preferredAlpha };
    const alpha = await isAlphaLabFrontend(`http://localhost:${port}`);
    if (alpha.ok) return { port, reused: true, reason: `found existing AlphaLab frontend on ${port}`, alphaCheck: alpha };
  }
  throw new Error(`No free frontend port found near ${preferredPort}`);
}

export async function run(input = {}) {
  const projectRoot = input.projectRoot || 'E:\\quant-framework';
  const backendPort = Number(input.backendPort || 8000);
  const preferredFrontendPort = Number(input.frontendPort || 5173);
  const waitTimeoutMs = Number(input.waitTimeoutMs || 60000);
  const backendUrl = `http://127.0.0.1:${backendPort}`;
  const frontendDir = path.join(projectRoot, 'dashboard', 'frontend');
  const conexusDir = path.join(projectRoot, '.conexus', 'alphalab-runner');
  ensureDir(conexusDir);
  const stateFile = path.join(conexusDir, 'state.json');
  const backendLog = path.join(conexusDir, 'backend.log');
  const frontendLog = path.join(conexusDir, 'frontend.log');

  if (!fs.existsSync(path.join(projectRoot, 'pyproject.toml'))) throw new Error(`Project root not found or invalid: ${projectRoot}`);
  if (!fs.existsSync(path.join(frontendDir, 'package.json'))) throw new Error(`Frontend package.json not found: ${frontendDir}`);

  if (input.installDeps !== false && !fs.existsSync(path.join(frontendDir, 'node_modules'))) {
    const install = runChecked(npmCmd(), ['ci', '--no-audit', '--no-fund'], frontendDir, 180000);
    if (install.status !== 0) throw new Error(`npm ci failed (${install.status}): ${install.stderr || install.stdout}`);
  }

  let backendPid = null;
  let frontendPid = null;
  const reused = { backend: false, frontend: false };
  const notes = [];

  const preBackend = await urlOk(`${backendUrl}/`);
  if (!preBackend.ok) {
    backendPid = startDetached('python', ['-m', 'uvicorn', 'dashboard.backend.main:app', '--reload', '--host', '127.0.0.1', '--port', String(backendPort)], projectRoot, backendLog);
  } else {
    reused.backend = true;
  }
  const backendCheck = await waitFor(`${backendUrl}/`, Math.min(waitTimeoutMs, 60000));

  const portChoice = await chooseFrontendPort(preferredFrontendPort);
  const frontendPort = portChoice.port;
  const frontendUrl = `http://localhost:${frontendPort}`;
  notes.push(portChoice.reason);
  if (portChoice.reused) {
    reused.frontend = true;
  } else {
    fs.appendFileSync(frontendLog, `\n\n--- starting ${new Date().toISOString()} on port ${frontendPort} ---\n`, 'utf8');
    frontendPid = startDetached(npmCmd(), ['run', 'dev:web', '--', '--host', '127.0.0.1', '--port', String(frontendPort), '--strictPort'], frontendDir, frontendLog);
  }
  const frontendCheck = await waitFor(frontendUrl, Math.min(waitTimeoutMs, 60000), isAlphaLabFrontend);

  const backendPids = pidsOnPort(backendPort);
  const frontendPids = pidsOnPort(frontendPort);
  if (!backendPid && backendPids.length) backendPid = backendPids[0];
  if (!frontendPid && frontendPids.length) frontendPid = frontendPids[0];

  if (input.openBrowser) {
    try {
      if (isWin()) spawn('cmd.exe', ['/c', 'start', '', frontendUrl], { detached: true, stdio: 'ignore' }).unref();
      else spawn('open', [frontendUrl], { detached: true, stdio: 'ignore' }).unref();
    } catch {}
  }

  const state = { projectRoot, backendPort, frontendPort, preferredFrontendPort, backendUrl, frontendUrl, backendPid, frontendPid, backendPids, frontendPids, reused, notes, backendLog, frontendLog, startedAt: new Date().toISOString() };
  fs.writeFileSync(stateFile, JSON.stringify(state, null, 2), 'utf8');
  const ok = Boolean(backendCheck.ok && frontendCheck.ok);
  return {
    ok,
    message: ok ? 'AlphaLab full stack is running.' : 'One or more services did not become healthy; inspect logs.',
    backendUrl,
    frontendUrl,
    backendPid,
    frontendPid,
    backendPids,
    frontendPids,
    reused,
    notes,
    stateFile,
    logs: { backendLog, frontendLog },
    checks: { backend: backendCheck, frontend: frontendCheck }
  };
}
